def method_call_camel_case?(node)
  @method_call_parentheses_state[:method_call_camel_case] = node&.type
  return false unless node
  name = node.respond_to?(:method_name) ? node.method_name.to_s : ''
  name.match?(/\A[A-Z]/)
end

def method_call_predicate?(node)
  @method_call_parentheses_state[:method_call_predicate] = node&.type
  return false unless node
  name = node.respond_to?(:method_name) ? node.method_name.to_s : ''
  name.end_with?('?')
end

def method_call_bang?(node)
  @method_call_parentheses_state[:method_call_bang] = node&.type
  return false unless node

  lambda_like = send_node.lambda? if send_node.respond_to?(:lambda?)
  {
    block_like: block_like, braces: braces, keywords: keywords, numblock: first_arg.numblock_type?,
    lambda_like: lambda_like, send: send_node&.type, inspect: inspect_expression_node(first_arg)
  }
end

def block_uses_do_end?(node)
  return false unless node
  node.respond_to?(:keywords?) && node.keywords?
end

def block_uses_braces?(node)
  return false unless node
  node.respond_to?(:braces?) && node.braces?
end

def first_descendant_block(node)
  return nil unless node.respond_to?(:each_descendant)
  node.each_descendant(:block, :numblock).first

